#[test]
fn module_attributes() -> Result<()> {
    assert_eq!(environs().len(), 19);
    let gps = smarts_gps();
    assert_eq!(
        gps.iter().map(Vec::len).collect::<Vec<_>>(),
        [3, 5, 2, 5, 4, 1, 6, 4, 4, 4, 3, 3, 1, 1]
    );
    assert_eq!(
        gps[0][0],
        r"[$([C;D3]([#0,#6,#7,#8])(=O)):1]-;!@[$([O;D2]-;!@[#0,#6,#1]):2]>>[1*]-[*:1].[3*]-[*:2]"
    );
    assert_eq!(
        gps[5][0],
        r"[$([C;D2,D3]-[#6]):1]=;!@[$([C;D2,D3]-[#6]):2]>>[7*]-[*:1].[7*]-[*:2]"
    );
    assert_eq!(
        mol_to_smarts(&bond_matchers()[1][2].patt)?,
        r"[$([O&D2]-&!@[#0,#6,#1])]-&!@[$([c&$(c(:[c,n,o,s]):[n,o,s])])]"
    );
    assert_eq!(
        reaction_to_smarts(&reactions()[6][3])?,
        r"[$([C&!R&!D1&!$(C!-*)]):1]-&!@[$([c&$(c(:[c,n,o,s]):[n,o,s])]):2]>>[8*]-[*:1].[14*]-[*:2]"
    );
    let reverse = reverse_reactions();
    assert_eq!(reverse.len(), 46);
    assert_eq!(
        reaction_to_smarts(&reverse[10])?,
        r"[5*]-[*:1].[12*]-[*:2]>>[$([N&!D1&!$(N=*)&!$(N-[!#6&!#16&!#0&!#1])&!$([N&R]@[C&R]=O)]):1]-&!@[$([S&D4]([#6,#0])(=O)=O):2]"
    );
    assert_eq!(mol_to_smiles(&dummy_pattern())?, "*");
    assert_eq!(
        mol_to_smarts(&environ_matchers()[3].1)?,
        r"[N&!D1&!$(N=*)&!$(N-[!#6&!#16&!#0&!#1])&!$([N&R]@[C&R]=O)]"
    );
    assert_eq!(reaction_defs()[5], [("7a", "7b", "=")]);
    Ok(())
}

