/// Python's test11: breaking BRICS bonds keeps every conformer, with each
/// dummy where the atom it replaces was.
#[test]
fn breaking_keeps_coordinates() -> Result<()> {
    use rdkit_cxx::chem::Conformer;
    let mut mol = mol_from_mol_block(BLOCK_3D)?;
    let check = |mol: &Mol, conf_id: i32| -> Result<()> {
        let frags = get_mol_frags_as_mols(&break_brics_bonds(mol)?)?;
        assert_eq!(frags.len(), 3);
        let sizes: Vec<u32> = frags.iter().map(|f| f.get_num_atoms()).collect();
        assert_eq!(sizes, [7, 3, 7]);
        let c1 = mol.get_conformer_with_id(conf_id)?;
        let same = |f: &Mol, i: u32, j: u32| -> Result<()> {
            let p = f.get_conformer_with_id(conf_id)?.get_atom_position(j)?;
            assert_eq!(c1.get_atom_position(i)?.distance(&p), 0.0);
            Ok(())
        };
        for i in 0..6 {
            same(&frags[0], i, i)?;
            same(&frags[2], i + 7, i)?;
        }
        same(&frags[0], 6, 6)?;
        same(&frags[2], 6, 6)?;
        same(&frags[1], 6, 0)?;
        same(&frags[1], 5, 1)?;
        Ok(())
    };
    check(&mol, 0)?;
    let conf = Conformer::from(mol_from_mol_block(BLOCK_2D)?.get_conformer()?);
    mol.add_conformer_with_assign_id(&conf, true)?;
    assert_eq!(mol.get_num_conformers(), 2);
    let frags = get_mol_frags_as_mols(&break_brics_bonds(&mol)?)?;
    assert!(frags.iter().all(|f| f.get_num_conformers() == 2));
    check(&mol, 0)?;
    check(&mol, 1)?;
    // Breaking given bonds keeps them too.
    let params = BreakBRICSBondsParams {
        bonds: Some(find_brics_bonds(&mol)?),
        ..Default::default()
    };
    let broken = break_brics_bonds_with_params(&mol, &params)?;
    assert_eq!(broken.get_num_conformers(), 2);
    assert_eq!(
        mol_to_smiles(&broken)?,
        mol_to_smiles(&break_brics_bonds(&mol)?)?
    );
    Ok(())
}
